def find_zero_components(grid):
    """Find all connected components of 0s"""
    rows = len(grid)
    cols = len(grid[0])

    visited = [[False]*cols for _ in range(rows)]
    components = []

    def dfs(r, c):
        stack = [(r,c)]
        while stack:
            cr, cc = stack.pop()
            if visited[cr][cc]: continue
            visited[cr][cc] = True
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = cr+dr, cc+dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == 0 and not visited[nr][nc]:
                        stack.append((nr, nc))

    comp_id = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                dfs(r,c)
                components.append([])

    # Now assign component IDs back
    comp_id = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                dfs(r,c)
                for pos in comp_id:
                    pass  # Already collected during DFS
                comp_id += 1

    return components

