    cols = len(grid[0])

    result = [row[:] for row in grid]

    # Count how many components each cell belongs to
    cell_comp = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                cell_comp[(r,c)] = component_ids[r][c]

