    unique_comps = set(cell_comp.values())
    for comp_id in unique_comps:
        # Get all cells in this component
        cells = [(r,c) for r in range(rows) for c in range(cols) 
                 if cell_comp.get((r,c)) == comp_id]

        if not cells:
            continue

        # Bounding box
        rmin = min(c[0] for c in cells)
        rmax = max(c[0] for c in cells)
        cmin = min(c[1] for c in cells)
        cmax = max(c[1] for c in cells)

        # Add 1-pixel border around bounding box
        for r in range(rmin-1, rmax+2):
            for c in range(cmin-1, cmax+2):
                if 0 <= r < rows and 0 <= c < cols:
                    # Border is any cell touching but not inside the rectangle
                    is_inside = (rmin <= r <= rmax) and (cmin <= c <= cmax)
                    touches = (abs(r-rmin)<=1 and abs(r-rmax)<=1) or \
                             (abs(c-cmin)<=1 and abs(c-cmax)<=1)

                    if touches and not is_inside:
                        # Only mark if it's currently 0
                        if result[r][c] == 0:
                            result[r][c] = 3

    return result

